-- ── MONITORS ─────────────────────────────────────────────────────────
-- Applied by Hyprland itself, inside the output-connect path, so they
-- cannot lose a startup race the way kanshi did. The EDID *preferred*
-- mode on the Lenovo R34w-30 is 3440x1440@59.97 — the 100 Hz mode has
-- to be named explicitly or you silently get 60.
--
-- The one rule that cannot live here is "turn the laptop panel off, but
-- only while the external is plugged in". That conditional is in
-- conf/monitors.sh, which applies it at startup and on every hotplug.
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
    output = "HDMI-A-1",
    mode = "3440x1440@99.98",
    position = "0x0",
    scale = "1",
})

hl.monitor({
    output = "eDP-1",
    mode = "1920x1080@144",
    position = "auto",
    scale = "1",
})

hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = "1",
})

require("conf.autostart")
require("conf.animations")
require("conf.environments")
require("conf.input")
require("conf.general")
require("conf.decoration")
require("conf.keybinds")
require("conf.window-rules")

hl.config({
    misc = {
        disable_hyprland_logo = true,
        disable_splash_rendering = true,
    },
    -- The two on-screen notices Hyprland renders itself -- the release-notes
    -- card after an update and the periodic donation appeal. Both are drawn
    -- by the compositor, not by dunst (dunst is bottom-RIGHT at 12px offset,
    -- see dunstrc), which is why no notification setting silenced them.
    ecosystem = {
        no_update_news = true,
        no_donation_nag = true,
    },
})

